import React from 'react';

export default function App() {
  return (
    <div style={{ padding: '20px', fontFamily: 'sans-serif' }}>
      <h1>CSS Flexbox 기초 실습</h1>

      <section style={{ marginBottom: '30px' }}>
        <h2>1. 가로 중앙 정렬</h2>
        <div style={containerStyle1}>
          <div style={itemStyle}>1</div>
          <div style={itemStyle}>2</div>
          <div style={itemStyle}>3</div>
        </div>
      </section>

      <section style={{ marginBottom: '30px' }}>
        <h2>2. 양 끝 정렬 및 세로 중앙 정렬</h2>
        <div style={containerStyle2}>
          <div style={itemStyle}>A</div>
          <div style={itemStyle}>B</div>
          <div style={itemStyle}>C</div>
        </div>
      </section>

      <section style={{ marginBottom: '30px' }}>
        <h2>3. 세로 방향 오른쪽 정렬</h2>
        <div style={containerStyle3}>
          <div style={itemStyle}>X</div>
          <div style={itemStyle}>Y</div>
          <div style={itemStyle}>Z</div>
        </div>
      </section>
    </div>
  );
}

const itemStyle = {
  width: '50px',
  height: '50px',
  backgroundColor: '#3b82f6',
  color: 'white',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  fontWeight: 'bold',
  borderRadius: '8px',
  margin: '4px',
};

// 요구사항 1: display: 'flex', justifyContent: 'center' 추가
const containerStyle1 = {
  border: '2px dashed #ccc',
  padding: '10px',
  minHeight: '80px',
};

// 요구사항 2: display: 'flex', justifyContent: 'space-between', alignItems: 'center' 추가
const containerStyle2 = {
  border: '2px dashed #ccc',
  padding: '10px',
  height: '100px',
};

// 요구사항 3: display: 'flex', flexDirection: 'column', alignItems: 'flex-end' 추가
const containerStyle3 = {
  border: '2px dashed #ccc',
  padding: '10px',
  minHeight: '200px',
};
